	"github.com/antonmedv/fx/internal/utils"
	"github.com/charmbracelet/x/term"
	"github.com/mattn/go-runewidth"
)

func (p *JsonParser) errorSnippet(message string) string {
	termWidth := 80
	if w, _, err := term.GetSize(os.Stdout.Fd()); err == nil {
		termWidth = w
	}

	maxWidth := utils.MinInt(termWidth, 60)
	indent := "  "

	lines := strings.Split(message, "\n")
	for i, line := range lines {
		if len(line) > maxWidth {
			lines[i] = line[:maxWidth-3] + "..."
		}
	}
	message = strings.Join(lines, "\n")

	pos := p.end - 1
	for pos > 0 && p.data[pos-1] != '\n' {
		pos--
	}
	end := pos
	for end < len(p.data) && p.data[end] != '\n' {
		end++
	}
	if end > pos && p.data[end-1] == '\r' {
		end--
	}
	s := string(p.data[pos:utils.MinInt(p.end+1, len(p.data))])

	width := runewidth.StringWidth(s)
	snippet := indent + s
	if width > maxWidth {
		snippet = indent + runewidth.Truncate(s, maxWidth, "...") + "\n"
		width = runewidth.StringWidth(snippet)
		snippet += indent + strings.Repeat(".", utils.MaxInt(0, width-1)) + "^"
	} else {
		snippet += "\n" + indent + strings.Repeat(".", utils.MaxInt(0, width-1)) + "^"
	}

	return fmt.Sprintf("%s\n%s", message, snippet)
}
EOF
